def test_contract():
    assert take_last([1,2],0)==[]; assert take_last([1,2],-1)==[]; assert take_last([1,2,3],2)==[2,3]; assert take_last([],3)==[]; assert take_last([1],5)==[1]

from engine import count_prefix
def test_contract():
    assert count_prefix(['ab','ba','abc'],'a')==2; assert count_prefix(['cab'],'a')==0; assert count_prefix([], 'a')==0; assert count_prefix(['a','b'],'')==2

from engine import running_total
def test_contract():
    assert running_total([1,2,3])==[1,3,6]; assert running_total([])==[]; assert running_total([-1,3,-2])==[-1,2,0]

from engine import word_counts
def test_contract():
    assert word_counts('A a B')=={'a':2,'b':1}; assert word_counts('')=={}; assert word_counts('x\tx')=={'x':2}; assert word_counts('  Hi  ')=={'hi':1}

