from engine import windows
def test_contract():
    assert windows([1,2,3],2)==[[1,2],[2,3]]; assert windows([1],1)==[[1]]; assert windows([],2)==[]; assert windows([1],3)==[]
    try:
        windows([1],0)
    except ValueError:
        pass
    else:
        raise AssertionError('zero size')

correct_source:
def windows(values, size):
    if size <= 0:
        raise ValueError('size must be positive')
    return [values[i:i+size] for i in range(max(0,len(values)-size+1))]

hidden_checks:
assert windows([1,2,3],2)==[[1,2],[2,3]]; assert windows([1],1)==[[1]]; assert windows([],2)==[]; assert windows([1],3)==[]
try:
    windows([1],0)
except ValueError:
    pass
else:
    raise AssertionError('zero size')

